<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3'; import MainLayout from '@/layouts/MainLayout.vue'; import BaseButton from '@/components/base/BaseButton.vue'
const props=defineProps({ account:{type:Object,required:true} }); const form=useForm({password:'',password_confirmation:''}); const submit=()=>form.put(`/admin/accounts/${props.account.id}/password`)
</script>
<template><Head title="Atur Ulang Kata Sandi"/><MainLayout><Link href="/admin/accounts" class="text-xs text-slate-500">← Akun Wilayah</Link><div class="mb-6 mt-4"><h2 class="text-2xl font-semibold text-slate-950">Atur ulang kata sandi</h2><p class="mt-2 text-sm text-slate-600">{{ account.name }} · {{ account.email }}</p></div><form class="max-w-xl space-y-5 rounded-xl border border-slate-200 bg-white p-6 shadow-sm" @submit.prevent="submit"><div><label for="password" class="mb-2 block text-sm font-medium">Kata sandi baru</label><input id="password" v-model="form.password" type="password" minlength="12" required autocomplete="new-password" class="h-11 w-full rounded-lg border border-slate-300 px-3.5 outline-none focus:border-[#2d2a70]"><p v-if="form.errors.password" role="alert" class="mt-2 text-sm text-red-600">{{ form.errors.password }}</p></div><div><label for="confirmation" class="mb-2 block text-sm font-medium">Konfirmasi kata sandi</label><input id="confirmation" v-model="form.password_confirmation" type="password" minlength="12" required autocomplete="new-password" class="h-11 w-full rounded-lg border border-slate-300 px-3.5 outline-none focus:border-[#2d2a70]"></div><div class="flex justify-end gap-3 border-t pt-5"><Link href="/admin/accounts" class="inline-flex h-11 items-center rounded-lg border px-5 text-sm">Batal</Link><BaseButton type="submit" :loading="form.processing" class="h-11">Simpan kata sandi</BaseButton></div></form></MainLayout></template>
